import { mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import * as schema from "./schema";

/**
 * The single Drizzle connection for the process.
 *
 * Repositories import `db` from `@/server/db` (the barrel), never this module
 * directly, so the connection can be swapped in tests. Never construct a
 * second `Database` — SQLite in WAL mode tolerates it, but the in-process
 * event bus assumes one writer.
 */

const DEFAULT_DB_PATH = "./data/taskflow.db";

let instance: ReturnType<typeof createClient> | null = null;

function createClient(path: string) {
  const absolute = resolve(process.cwd(), path);
  mkdirSync(dirname(absolute), { recursive: true });
  const sqlite = new Database(absolute);
  sqlite.pragma("journal_mode = WAL");
  sqlite.pragma("foreign_keys = ON");
  return drizzle(sqlite, { schema });
}

export function getDb(path: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH) {
  instance ??= createClient(path);
  return instance;
}

/** Test hook: point the singleton at an in-memory database. */
export function useInMemoryDb(): void {
  instance = createClient(":memory:");
}

export type Db = ReturnType<typeof getDb>;
export type DbSchema = typeof schema;
     allow_public_projects INTEGER NOT NULL DEFAULT 0,
     require_two_factor INTEGER NOT NULL DEFAULT 0,
     digest_hour_utc INTEGER NOT NULL DEFAULT 7,
     enabled_flag_overrides TEXT NOT NULL DEFAULT '[]',
     created_at TEXT NOT NULL,
     updated_at TEXT NOT NULL,
     archived_at TEXT
   )`,
  `CREATE UNIQUE INDEX IF NOT EXISTS organizations_slug_idx ON organizations (slug)`,
  `CREATE INDEX IF NOT EXISTS organizations_owner_idx ON organizations (owner_id)`,
  `CREATE TABLE IF NOT EXISTS organization_usage (
     org_id TEXT PRIMARY KEY NOT NULL,
     seats_used INTEGER NOT NULL DEFAULT 0,
     projects_used INTEGER NOT NULL DEFAULT 0,
     issues_used INTEGER NOT NULL DEFAULT 0,
     storage_mb_used INTEGER NOT NULL DEFAULT 0,
     measured_at TEXT NOT NULL
   )`,
  `CREATE TABLE IF NOT EXISTS members (
     id TEXT PRIMARY KEY NOT NULL,
     org_id TEXT NOT NULL,
     user_id TEXT NOT NULL,
     role TEXT NOT NULL DEFAULT 'member',
     status TEXT NOT NULL DEFAULT 'active',
     invited_by TEXT,
     joined_at TEXT,
     last_seen_at TEXT,
     created_at TEXT NOT NULL,
     updated_at TEXT NOT NULL,
     archived_at TEXT
   )`,
  `CREATE UNIQUE INDEX IF NOT EXISTS members_org_user_idx ON members (org_id, user_id)`,
  `CREATE INDEX IF NOT EXISTS members_org_role_idx ON members (org_id, role)`,
  `CREATE TABLE IF NOT EXISTS invitations (
     id TEXT PRIMARY KEY NOT NULL,
     org_id TEXT NOT NULL,
     email TEXT NOT NULL,
     role TEXT NOT NULL DEFAULT 'member',
     invited_by TEXT NOT NULL,
     token_hash TEXT NOT NULL,
     expires_at TEXT NOT NULL,
     accepted_at TEXT,
     revoked_at TEXT,
     created_at TEXT NOT NULL,
     updated_at TEXT NOT NULL
   )`,
  `CREATE UNIQUE INDEX IF NOT EXISTS invitations_token_idx ON invitations (token_hash)`,
  `CREATE INDEX IF NOT EXISTS invitations_org_email_idx ON invitations (org_id, email)`,
  `CREATE TABLE IF NOT EXISTS projects (
     id TEXT PRIMARY KEY NOT NULL,
     org_id TEXT NOT NULL,
     name TEXT NOT NULL,
     slug TEXT NOT NULL,
     key TEXT NOT NULL,
     description TEXT,
     visibility TEXT NOT NULL DEFAULT 'org',
     status TEXT NOT NULL DEFAULT 'active',
     lead_id TEXT,
     color TEXT NOT NULL DEFAULT '#6366f1',
     starts_at TEXT,
     target_date TEXT,
     created_at TEXT NOT NULL,
     updated_at TEXT NOT NULL,
     archived_at TEXT
   )`,
  `CREATE UNIQUE INDEX IF NOT EXISTS projects_org_slug_idx ON projects (org_id, slug)`,
  `CREATE UNIQUE INDEX IF NOT EXISTS projects_org_key_idx ON projects (org_id, key)`,
  `CREATE INDEX IF NOT EXISTS projects_org_archived_idx ON projects (org_id, archived_at)`,
  `CREATE TABLE IF NOT EXISTS project_members (
     org_id TEXT NOT NULL,
     project_id TEXT NOT NULL,
     user_id TEXT NOT NULL,
     added_at TEXT NOT NULL
   )`,
  `CREATE UNIQUE INDEX IF NOT EXISTS project_members_pk ON project_members (project_id, user_id)`,
  `CREATE INDEX IF NOT EXISTS project_members_org_idx ON project_members (org_id)`,
  `CREATE TABLE IF NOT EXISTS issues (
     id TEXT PRIMARY KEY NOT NULL,
     org_id TEXT NOT NULL,
     project_id TEXT NOT NULL,
     number INTEGER NOT NULL,
     bucket_key TEXT NOT NULL,
     tokens INTEGER NOT NULL,
     refilled_at TEXT NOT NULL
   )`,
  `CREATE INDEX IF NOT EXISTS rate_limit_org_key_idx ON rate_limit_buckets (org_id, bucket_key)`,
  `CREATE TABLE IF NOT EXISTS search_index (
     id TEXT PRIMARY KEY NOT NULL,
     org_id TEXT NOT NULL,
     subject_kind TEXT NOT NULL,
     subject_id TEXT NOT NULL,
     project_id TEXT,
     content TEXT NOT NULL,
     indexed_at TEXT NOT NULL
   )`,
  `CREATE INDEX IF NOT EXISTS search_index_org_kind_idx ON search_index (org_id, subject_kind)`,
];

/**
 * Brings `databasePath` up to date. Generated migrations win when they exist;
 * otherwise the embedded schema is pushed. Safe to run repeatedly — every
 * statement is `IF NOT EXISTS`.
 */
export async function runMigrations(
  databasePath: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH,
): Promise<void> {
  const absolute = resolve(process.cwd(), databasePath);
  mkdirSync(dirname(absolute), { recursive: true });

  const sqlite = new Database(absolute);
  sqlite.pragma("journal_mode = WAL");

  try {
    for (const statement of readMigrationStatements()) {
      sqlite.exec(statement);
    }
  } finally {
    sqlite.close();
  }
}

/** `pnpm db:migrate` runs this file directly; importing it must stay inert. */
if (process.argv[1]?.endsWith("migrate.ts") === true) {
  await runMigrations();
}

function readMigrationStatements(): readonly string[] {
  const dir = resolve(process.cwd(), MIGRATIONS_DIR);
  if (!existsSync(dir)) return SCHEMA_STATEMENTS;

  const files = readdirSync(dir)
    .filter((name) => name.endsWith(".sql"))
    .sort();

  if (files.length === 0) return SCHEMA_STATEMENTS;

  return files.flatMap((name) =>
    readFileSync(join(dir, name), "utf8")
      .split("--> statement-breakpoint")
      .map((chunk) => chunk.trim())
      .filter(Boolean),
  );
}
/**
 * Renders react-email templates and 'sends' them by writing the draft to the log. No network egress.
 */
import { createLogger } from "@/lib/logger";

export type OutgoingEmail = {
  to: string;
  subject: string;
  html: string;
  text: string;
};

export type RenderedEmail = { subject: string; html: string; text: string };

export type EmailTemplate =
  | "invite"
  | "digest"
  | "mention"
  | "invoice"
  | "welcome"
  | "password-reset"
  | "overdue";

const logger = createLogger("email-service");

/** Subject lines per template; the props fill in the bracketed parts. */
const SUBJECTS: Readonly<Record<EmailTemplate, string>> = {
  invite: "You have been invited to a Taskflow workspace",
  digest: "Your Taskflow digest",
  mention: "You were mentioned in Taskflow",
  invoice: "Your Taskflow invoice",
  welcome: "Welcome to Taskflow",
  "password-reset": "Reset your Taskflow password",
  overdue: "You have overdue issues",
};

/**
 * "Sends" a message. Taskflow has no outbound mail transport by design — the
 * corpus must build and run offline — so delivery means writing the draft to
 * the structured log, where the dev tools tab surfaces it.
 */
export async function sendEmail(message: OutgoingEmail): Promise<void> {
  logger.info("email.sent", {
    to: message.to,
    subject: message.subject,
    bytes: message.html.length,
  });
}

/**
 * Renders a template to both an HTML and a plain-text body. The text half is
 * derived from the HTML rather than written twice, so the two can never drift.
 */
export async function renderEmail(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): Promise<RenderedEmail> {
  const subject = subjectFor(template, props);
  const html = renderBody(template, props);

  return { subject, html, text: toPlainText(html) };
}

function subjectFor(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const base = SUBJECTS[template];
  const orgName = props.orgName;
  return typeof orgName === "string" ? `${base} — ${orgName}` : base;
}

function renderBody(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const rows = Object.entries(props)
    .filter(([, value]) => value !== null && value !== undefined)
    .map(
      ([key, value]) =>
        `<tr><td>${escapeHtml(key)}</td><td>${escapeHtml(String(value))}</td></tr>`,
    )
    .join("");

  return [
    `<html><body><h1>${escapeHtml(SUBJECTS[template])}</h1>`,
    `<table>${rows}</table>`,
    "</body></html>",
  ].join("");
}

function toPlainText(html: string): string {
  return html
    .replace(/<\/(?:tr|h1|p|div)>/g, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

