/**
 * A removed member is a former member for every purpose, and can be invited
 * back as the member the workspace already knew.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import { toAppError } from "@/lib/errors";
import { hashToken } from "@/lib/hash";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { NotCurrentMemberError } from "@/lib/tenant";
import { runOverdueIssueJob, resetOverdueTracking } from "@/server/jobs/overdue-issue-job";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import * as digestService from "@/server/services/digest-service";
import * as emailService from "@/server/services/email-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import * as projectService from "@/server/services/project-service";
import * as sessionService from "@/server/services/session-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { notify } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, OrgId, UserId } from "@/types/common";
import type { Member, Role, SessionPrincipal } from "@/types/member";

let cleanup: () => void;
let detachUsage: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachUsage = registerUsageListeners();
});

afterAll(() => {
  detachUsage();
  cleanup();
});

afterEach(() => {
  vi.restoreAllMocks();
});

/** Adds a member to the tenant through the repository and returns the row. */
async function addMember(
  tenant: Tenant,
  name: string,
  role: Role = "member",
): Promise<{ userId: UserId; member: Member }> {
  const user = await userRepo.insertUser({
    email: `${name}@${tenant.org.slug}.test`,
    name,
    passwordHash: "seed",
  });
  const member = await memberRepo.insertMember(tenant.org.id, user.id, role, null);
  return { userId: user.id, member };
}

function principalFor(userId: UserId, orgId: OrgId): SessionPrincipal {
  return {
    userId,
    email: "someone@example.test",
    activeOrgId: orgId,
    expiresAt: new Date(Date.now() + 3_600_000).toISOString() as never,
  };
}

let tokenSeq = 0;
async function inviteToken(tenant: Tenant, role: Role = "member"): Promise<string> {
  tokenSeq += 1;
  const token = `${String(tokenSeq).padStart(4, "0")}`.repeat(8);
  await invitationRepo.insertInvitation(
    tenant.org.id,
    { orgId: tenant.org.id, email: `invitee${tokenSeq}@x.test`, role, expiresInDays: 14 },
    tenant.userIds.admin,
    hashToken(token),
  );
  return token;
}

describe("a removed member cannot act or switch into the workspace", () => {
  it("resolves no actor, cannot switch in and is not in the org picker", async () => {
    const tenant = await createTenant("fm-session");
    const { userId, member } = await addMember(tenant, "contractor");

    const principal = principalFor(userId, tenant.org.id);
    await expect(sessionService.resolveActorForOrg(principal, tenant.org.slug)).resolves.not.toBeNull();

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    await expect(sessionService.resolveActorForOrg(principal, tenant.org.slug)).resolves.toBeNull();
    await expect(memberService.resolveActor(userId, tenant.org.id)).resolves.toBeNull();
    await expect(
      sessionService.switchActiveOrg(principal, { orgId: tenant.org.id }),
    ).rejects.toThrow(/not a member/);
    await expect(orgRepo.listOrgsForUser(userId)).resolves.toEqual([]);
  });

  it("leaves their memberships in other workspaces untouched", async () => {
    const home = await createTenant("fm-home");
    const other = await createTenant("fm-other");
    const { userId, member } = await addMember(home, "both");
    await memberRepo.insertMember(other.org.id, userId, "member", null);

    await memberService.removeMember(home.actors.owner, {
      orgId: home.org.id,
      memberId: member.id,
    });

    await expect(memberService.resolveActor(userId, other.org.id)).resolves.not.toBeNull();
    const orgs = await orgRepo.listOrgsForUser(userId);
    expect(orgs.map((org) => org.id)).toEqual([other.org.id]);
  });
});

describe("removing a member twice, or changing a removed member's role", () => {
  it("is a conflict and frees no further seat", async () => {
    const tenant = await createTenant("fm-twice");
    const { member } = await addMember(tenant, "leaver");
    await usageRepo.recomputeUsage(tenant.org.id);

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });
    const seatsAfterFirst = (await usageRepo.getUsage(tenant.org.id)).seatsUsed;

    const again = memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });
    await expect(again).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(toAppError(await again.catch((error: unknown) => error)).code).toBe("conflict");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
        role: "admin",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(seatsAfterFirst);
    const archived = await memberRepo.findMemberById(tenant.org.id, member.id);
    expect(archived?.role).toBe("member");
  });
});

describe("a former member is not notified", () => {
  it("skips them for every kind of notification, mentions and overdue included", async () => {
    const tenant = await createTenant("fm-notify");
    const { userId, member } = await addMember(tenant, "gone");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Opened by gone" }),
    );

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    const rows = await notify(
      tenant.org.id,
      "comment_created",
      [userId, tenant.userIds.admin],
      { title: "t", body: "b", href: "/h", actorId: null },
    );
    expect(rows.map((row) => row.recipientId)).toEqual([tenant.userIds.admin]);

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: issue.createdAt,
      commentId: "cmt-fm-1" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [userId],
    });
    await emit("issue.overdue", {
      orgId: tenant.org.id,
      actorId: null,
      occurredAt: issue.createdAt,
      issueId: issue.id,
      projectId: tenant.project.id,
      dueAt: issue.createdAt,
      assigneeId: userId,
    });

    const page = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: userId,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(page.total).toBe(0);
  });

  it("ignores their handle when a comment mentions it", async () => {
    const tenant = await createTenant("fm-mention");
    const { member } = await addMember(tenant, "ghost");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mention target" }),
    );

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ping @ghost and @admin",
      parentId: null,
      mentionedUserIds: [member.userId],
    });
    expect(comment.mentionedUserIds).toEqual([tenant.userIds.admin]);
  });

  it("drops them from the digest recipients and the digest run", async () => {
    const tenant = await createTenant("fm-digest");
    await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { digestHourUtc: 3 },
    });
    await usageRepo.recomputeUsage(tenant.org.id);

    const { userId, member } = await addMember(tenant, "digester");
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId,
      kind: "comment_created",
      inApp: false,
      email: false,
      digestOnly: true,
    });
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: userId,
      kind: "comment_created",
      title: "Unread",
      body: "Unread",
      href: "/issues/1",
      actorId: null,
      channels: ["email"],
    });
    await expect(digestService.listDigestRecipients(tenant.org.id)).resolves.toEqual([userId]);

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    await expect(digestService.listDigestRecipients(tenant.org.id)).resolves.toEqual([]);

    const now = new Date();
    const windowEnd = now.toISOString() as never;
    const windowStart = new Date(now.getTime() - 86_400_000).toISOString() as never;
    await expect(
      digestService.buildDigest(tenant.org.id, userId, windowStart, windowEnd),
    ).resolves.toBeNull();

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    await runDigestEmailJob(new Date(Date.UTC(2026, 5, 1, 3)));
    expect(sendSpy).not.toHaveBeenCalled();
  });

  it("stops the overdue job from alerting an issue's former assignee", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("fm-overdue");
    const { userId, member } = await addMember(tenant, "late");
    await usageRepo.recomputeUsage(tenant.org.id);

    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late one",
        assigneeId: userId,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
      tenant.userIds.owner,
      number,
    );

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });
    await runOverdueIssueJob(new Date("2026-06-01T07:00:00.000Z"));

    const page = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: userId,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(page.total).toBe(0);
  });
});

describe("work cannot be handed to someone outside the workspace", () => {
  it("refuses assignees and leads who are former or foreign, changing nothing", async () => {
    const tenant = await createTenant("fm-work");
    const stranger = await createTenant("fm-work-elsewhere");
    const { userId, member } = await addMember(tenant, "departed");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Held by departed", assigneeId: userId }),
    );
    const led = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Led by departed",
      slug: "led-by-departed",
      key: "LED",
      description: null,
      visibility: "org",
      leadId: userId,
      color: "#6366f1",
      targetDate: null,
    });
    expect(led.leadId).toBe(userId);

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    // Their issues become unassigned and their projects have no lead.
    const after = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(after?.assigneeId).toBeNull();
    const project = await projectRepo.findProjectById(tenant.org.id, led.id);
    expect(project?.leadId).toBeNull();

    // Nothing more can be handed to them, or to a member of another org.
    for (const outsider of [userId, stranger.userIds.member]) {
      await expect(
        issueService.assignIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          assigneeId: outsider,
        }),
      ).rejects.toBeInstanceOf(NotCurrentMemberError);

      await expect(
        issueService.createIssue(
          tenant.actors.member,
          issueInput(tenant.org.id, tenant.project.id, { title: "Refused", assigneeId: outsider }),
        ),
      ).rejects.toBeInstanceOf(NotCurrentMemberError);

      await expect(
        projectService.createProject(tenant.actors.admin, {
          orgId: tenant.org.id,
          name: "Refused project",
          slug: "refused-project",
          key: "REF",
          description: null,
          visibility: "org",
          leadId: outsider,
          color: "#6366f1",
          targetDate: null,
        }),
      ).rejects.toBeInstanceOf(NotCurrentMemberError);

      await expect(
        projectService.updateProject(tenant.actors.admin, {
          orgId: tenant.org.id,
          projectId: led.id,
          name: "Renamed",
          leadId: outsider,
        }),
      ).rejects.toBeInstanceOf(NotCurrentMemberError);
    }

    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.assigneeId).toBeNull();
    expect((await projectRepo.findProjectById(tenant.org.id, led.id))?.name).toBe("Led by departed");
    expect(await projectRepo.findProjectBySlug(tenant.org.id, "refused-project")).toBeNull();
    const titles = (
      await issueRepo.listIssues({ orgId: tenant.org.id, limit: 25, cursor: null })
    ).items.map((row) => row.title);
    expect(titles).not.toContain("Refused");

    // Un-assigning stays allowed, and a current member can still be assigned.
    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.admin,
      }),
    ).resolves.toMatchObject({ assigneeId: tenant.userIds.admin });
    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: null,
      }),
    ).resolves.toMatchObject({ assigneeId: null });
  });
});

describe("inviting a former member back", () => {
  it("re-admits the same membership, once, with the invitation's role and inviter", async () => {
    const tenant = await createTenant("fm-readmit");
    const { userId, member } = await addMember(tenant, "designer");
    await memberRepo.touchLastSeen(
      tenant.org.id,
