    const principal = principalFor(userId, tenant.org.id);
    await expect(sessionService.resolveActorForOrg(principal, tenant.org.slug)).resolves.not.toBeNull();

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    await expect(sessionService.resolveActorForOrg(principal, tenant.org.slug)).resolves.toBeNull();
    await expect(memberService.resolveActor(userId, tenant.org.id)).resolves.toBeNull();
    await expect(
      sessionService.switchActiveOrg(principal, { orgId: tenant.org.id }),
    ).rejects.toThrow(/not a member/);
    await expect(orgRepo.listOrgsForUser(userId)).resolves.toEqual([]);
  });

  it("leaves their memberships in other workspaces untouched", async () => {
    const home = await createTenant("fm-home");
    const other = await createTenant("fm-other");
    const { userId, member } = await addMember(home, "both");
    await memberRepo.insertMember(other.org.id, userId, "member", null);

