describe("work cannot be handed to someone outside the workspace", () => {
  it("refuses assignees and leads who are former or foreign, changing nothing", async () => {
    const tenant = await createTenant("fm-work");
    const stranger = await createTenant("fm-work-elsewhere");
    const { userId, member } = await addMember(tenant, "departed");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Held by departed", assigneeId: userId }),
    );
    const led = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Led by departed",
      slug: "led-by-departed",
      key: "LED",
      description: null,
      visibility: "org",
      leadId: userId,
      color: "#6366f1",
      targetDate: null,
    });
    expect(led.leadId).toBe(userId);

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    // Their issues become unassigned and their projects have no lead.
    const after = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(after?.assigneeId).toBeNull();
    const project = await projectRepo.findProjectById(tenant.org.id, led.id);
    expect(project?.leadId).toBeNull();

    // Nothing more can be handed to them, or to a member of another org.
    for (const outsider of [userId, stranger.userIds.member]) {
      await expect(
        issueService.assignIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          assigneeId: outsider,
        }),
      ).rejects.toBeInstanceOf(NotCurrentMemberError);

      await expect(
        issueService.createIssue(
          tenant.actors.member,
          issueInput(tenant.org.id, tenant.project.id, { title: "Refused", assigneeId: outsider }),
        ),
      ).rejects.toBeInstanceOf(NotCurrentMemberError);

      await expect(
        projectService.createProject(tenant.actors.admin, {
          orgId: tenant.org.id,
          name: "Refused project",
          slug: "refused-project",
          key: "REF",
          description: null,
          visibility: "org",
          leadId: outsider,
          color: "#6366f1",
          targetDate: null,
        }),
      ).rejects.toBeInstanceOf(NotCurrentMemberError);

      await expect(
        projectService.updateProject(tenant.actors.admin, {
          orgId: tenant.org.id,
          projectId: led.id,
          name: "Renamed",
          leadId: outsider,
        }),
      ).rejects.toBeInstanceOf(NotCurrentMemberError);
    }

    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.assigneeId).toBeNull();
    expect((await projectRepo.findProjectById(tenant.org.id, led.id))?.name).toBe("Led by departed");
    expect(await projectRepo.findProjectBySlug(tenant.org.id, "refused-project")).toBeNull();
    const titles = (
      await issueRepo.listIssues({ orgId: tenant.org.id, limit: 25, cursor: null })
    ).items.map((row) => row.title);
    expect(titles).not.toContain("Refused");

    // Un-assigning stays allowed, and a current member can still be assigned.
    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.admin,
      }),
    ).resolves.toMatchObject({ assigneeId: tenant.userIds.admin });
    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: null,
      }),
    ).resolves.toMatchObject({ assigneeId: null });
  });
});

describe("inviting a former member back", () => {
  it("re-admits the same membership, once, with the invitation's role and inviter", async () => {
    const tenant = await createTenant("fm-readmit");
    const { userId, member } = await addMember(tenant, "designer");
    await memberRepo.touchLastSeen(
      tenant.org.id,
      userId,
      "2026-02-02T02:02:02.000Z" as never,
    );
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId,
      kind: "comment_created",
      inApp: true,
      email: false,
      digestOnly: false,
    });
    const before = await memberRepo.findMemberById(tenant.org.id, member.id);

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });
    await usageRepo.recomputeUsage(tenant.org.id);
    const seatsWhileGone = await memberRepo.countActiveMembers(tenant.org.id);

    const token = await inviteToken(tenant, "viewer");
    const returned = await invitationService.acceptInvitation(userId, { token });

    expect(returned.id).toBe(member.id);
    expect(returned).toMatchObject({
      status: "active",
      archivedAt: null,
      role: "viewer",
      invitedBy: tenant.userIds.admin,
      lastSeenAt: before?.lastSeenAt,
      createdAt: before?.createdAt,
    });

    const invitation = await invitationRepo.findInvitationByTokenHash(hashToken(token));
    expect(invitation?.acceptedAt).not.toBeNull();
    expect(returned.joinedAt).toBe(invitation?.acceptedAt);

    // Listed once, one seat, an actor again, and their preferences came back.
    const page = await memberRepo.listMembers({ orgId: tenant.org.id, limit: 50, cursor: null });
    expect(page.items.filter((row) => row.userId === userId)).toHaveLength(1);
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(seatsWhileGone + 1);
    await expect(memberService.resolveActor(userId, tenant.org.id)).resolves.toMatchObject({
      role: "viewer",
    });
    await expect(
      preferenceRepo.getPreference(tenant.org.id, userId, "comment_created"),
    ).resolves.toMatchObject({ email: false });

    // Notified again from then on.
    const rows = await notify(tenant.org.id, "comment_created", [userId], {
      title: "t",
      body: "b",
      href: "/h",
      actorId: null,
    });
    expect(rows).toHaveLength(1);

    // The invitation is used up.
    await expect(invitationService.acceptInvitation(userId, { token })).rejects.toThrow(
      /already been accepted/,
    );
  });

  it("changes nothing for a current member who accepts, but uses the invitation up", async () => {
    const tenant = await createTenant("fm-current");
    const { userId, member } = await addMember(tenant, "already-in", "admin");
    const seatsBefore = await memberRepo.countActiveMembers(tenant.org.id);

    const token = await inviteToken(tenant, "viewer");
    const returned = await invitationService.acceptInvitation(userId, { token });

    expect(returned).toEqual(member);
    expect(await memberRepo.findMemberById(tenant.org.id, member.id)).toEqual(member);
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(seatsBefore);

    const someoneElse = await userRepo.insertUser({
      email: "someone-else@fm-current.test",
      name: "Someone",
      passwordHash: "seed",
    });
    await expect(
      invitationService.acceptInvitation(someoneElse.id, { token }),
    ).rejects.toThrow(/already been accepted/);
  });
});

