/**
 * Membership rows. Every read is filtered by `orgId`; removal is a soft delete.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import { and, count, desc, eq, inArray, isNotNull, isNull, like, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  AlreadyArchivedError,
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import { getDb, issues, members, projects, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toMember, toUser } from "./_mappers";
import type { ListMembersInput } from "@/schemas/member";
import type { IsoTimestamp, MemberId, OrgId, Page, UserId } from "@/types/common";
import type { Member, MemberWithUser, Role } from "@/types/member";

/**
 * A removed member is archived, never deleted, and no read ever surfaces one:
 * the scope is fixed here rather than threaded through every call site.
 */
const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};

function liveMemberPredicate() {
  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
}

/**
 * SQL twin of `isCurrentMember()`: an active membership that has not ended.
 * Every query that has to answer "may this person still take part?" composes
 * this rather than testing `status` or `archived_at` on its own.
 */
export function currentMemberPredicate() {
  return and(eq(members.status, "active"), liveMemberPredicate());
}

/**
 * The (org, user) lookup behind every actor resolution. The pair is unique,
 * so the row itself says whether the membership is usable: callers read
 * `status`, and an ended membership keeps its `archivedAt` for the audit log.
 */
export async function findMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .get();
  return row ? toMember(row) : null;
}

/** The membership only while it is current; `null` for a former member. */
export async function findCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        currentMemberPredicate(),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

/** Which of `userIds` are current members of the org. */
export async function filterCurrentMemberIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  if (userIds.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, [...userIds]),
        currentMemberPredicate(),
      ),
    )
    .all();

  return new Set(rows.map((row) => row.userId as UserId));
}

export async function findMemberById(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .get();
  return row ? toMember(row) : null;
}

/** Cursor-paged member list joined with the user record the UI renders. */
export async function listMembers(
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  const db = getDb();
  const sort = { sortColumn: members.createdAt, idColumn: members.id };

  const filters = compact(
    orgPredicate(members.orgId, input.orgId),
    liveMemberPredicate(),
    input.role === undefined ? undefined : eq(members.role, input.role),
    input.status === undefined ? undefined : eq(members.status, input.status),
    input.query === undefined
      ? undefined
      : or(
          like(users.name, `%${input.query}%`),
          like(users.email, `%${input.query}%`),
        ),
  );

  const total = db
    .select({ value: count() })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters))
    .get();

  const rows = db
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(members.createdAt), desc(members.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
  );
}

/** The seat count every plan check compares against. */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), currentMemberPredicate()))
    .get();
  return row?.value ?? 0;
}

export async function insertMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
  at: IsoTimestamp = toIsoTimestamp(new Date()),
): Promise<Member> {
  const stamp = at;
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMember(row);
}

export async function updateMemberRole(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ role, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

/**
 * Removal is a soft delete so the audit log keeps pointing at a real row.
 * `status` is left as it was: it records what the membership was, and
 * `archivedAt` alone says that it ended.
 *
 * In the same transaction the person is detached from the work they held in
 * this org: their issues become unassigned and the projects they led have no
 * lead. Rows that merely mention them — preferences, private-project access —
 * are left alone so that a re-admitted member finds them as they were.
 * Ending a membership that has already ended is a conflict, not a second
 * removal.
 */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const patch = archivePatch();

  const row = getDb().transaction((tx) => {
    const archived = tx
      .update(members)
      .set(patch)
      .where(
        and(
          orgPredicate(members.orgId, orgId),
          eq(members.id, memberId),
          liveMemberPredicate(),
        ),
      )
      .returning()
      .get();
    if (!archived) return undefined;

    tx.update(issues)
      .set({ assigneeId: null, updatedAt: patch.updatedAt })
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.assigneeId, archived.userId),
        ),
      )
      .run();

    tx.update(projects)
      .set({ leadId: null, updatedAt: patch.updatedAt })
      .where(
        and(
          orgPredicate(projects.orgId, orgId),
          eq(projects.leadId, archived.userId),
        ),
      )
      .run();

    return archived;
  });

  if (row) return toMember(row);

  const existing = await findMemberById(orgId, memberId);
  if (existing) throw new AlreadyArchivedError("Member", memberId);
  throw new Error(`Member ${memberId} not found in org ${orgId}`);
}

/**
 * Brings a former member back as the same membership: same row and id, with
 * everything recorded about it still attached, active again under the role and
 * inviter of the invitation being accepted and joined at `at`. Only an ended
 * membership can be reinstated.
 */
export async function reinstateMember(
  orgId: OrgId,
  memberId: MemberId,
  grant: { role: Role; invitedBy: UserId | null; at: IsoTimestamp },
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({
      ...restorePatch(new Date(grant.at)),
      status: "active",
      role: grant.role,
      invitedBy: grant.invitedBy,
      joinedAt: grant.at,
    })
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.id, memberId),
        isNotNull(members.archivedAt),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} is not a former member of org ${orgId}`);
  return toMember(row);
}

export async function touchLastSeen(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(members)
    .set({ lastSeenAt: at })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .run();
}
